parameters.jsCode:
const metricsRes = $input.first().json || {};
const summary = metricsRes.summary || {};
const dateRange = metricsRes.dateRange || 'Past 7 Days';
const topProducts = Array.isArray(metricsRes.topProducts) ? metricsRes.topProducts : [];
const inventoryWatch = metricsRes.inventoryWatch || {};
const criticalItems = Array.isArray(inventoryWatch.items) ? inventoryWatch.items : [];

const totalRevenue = (summary.totalRevenue || 0).toLocaleString('en-IN');
const totalOrders = summary.totalOrders || 0;
const aov = (summary.aov || 0).toLocaleString('en-IN');
const delivered = summary.deliveredCount || 0;
const inProgress = (summary.shippedCount || 0) + (summary.processingCount || 0);
const pending = summary.pendingCount || 0;
const cancelled = summary.cancelledCount || 0;

// Format Top Products section
let topProductsText = '• No orders recorded in this period.';
if (topProducts.length > 0) {
  topProductsText = topProducts
    .map(p => `• *${p.name}*: ${p.quantity} units (₹${(p.revenue || 0).toLocaleString('en-IN')})`)
    .join('\n');
}

// Format Inventory Watch section
let inventoryText = '• All stock levels are healthy.';
if (criticalItems.length > 0) {
  inventoryText = criticalItems
    .map(i => `• *${i.product}* (${i.shade}): ${i.stock} remaining (Low)`)
    .join('\n');
}

// Build professional English executive digest message for Founder
const digestMessage = `📊 *CEVONNE EXECUTIVE WEEKLY DIGEST*\n` +
  `📅 *Period:* ${dateRange}\n\n` +
  `💰 *Revenue & Performance:*\n` +
  `• Total Revenue: *₹${totalRevenue}*\n` +
  `• Total Orders: *${totalOrders}*\n` +
  `• Average Order Value (AOV): *₹${aov}*\n` +
  `• Delivered: *${delivered}*\n` +
  `• Shipped / In-Transit: *${inProgress}*\n` +
  `• Pending Payment: *${pending}*\n` +
  `• Cancelled / Returned: *${cancelled}*\n\n` +
  `🏆 *Top Performing Shades:*\n` +
  `${topProductsText}\n\n` +
  `📦 *Inventory Watch:*\n` +
  `${inventoryText}\n\n` +
  `💡 *Weekly Focus:*\n` +
  `• Automated cart recovery and inventory alerts are active.\n` +
  `• Keep buffer stock ready for high-demand shades.\n\n` +
  `Have a high-growth and successful week ahead! 🚀`;

return [{
  json: {
    status: 'SUCCESS',
    date_range: dateRange,
    total_revenue: summary.totalRevenue || 0,
    total_orders: totalOrders,
    aov: summary.aov || 0,
    delivered_count: delivered,
    top_products: topProducts,
    critical_inventory_count: criticalItems.length,
    digest_message: digestMessage,
    generated_at: new Date().toISOString()
  }
}];

